package cz.mh.rallye.rallye_backend.participation;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import jakarta.servlet.http.Cookie;
import cz.mh.rallye.rallye_backend.participation.api.*;import cz.mh.rallye.rallye_backend.participation.application.*;import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@WebMvcTest(CrewStartController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class,StartCodePrivacyFilter.class,CrewStartThrottleFilter.class})
class CrewStartHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean CrewStartService service;@MockitoBean CrewStartAttempts attempts;
 final UUID event=UUID.randomUUID(),reg=UUID.randomUUID(),device=UUID.randomUUID(),run=UUID.randomUUID(),code=UUID.randomUUID();final String token=new SecretTokens().create(),secret=new SecretTokens().create(),base="/api/v1/race-events/"+event+"/registrations/"+reg;final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 @BeforeEach void login(){when(auth.authenticate(token)).thenReturn(actor);when(auth.authenticateReadOnly(token)).thenReturn(actor);}
 String body(){return "{\"registrationVersion\":1,\"code\":\"ABC123\",\"deviceSecret\":\""+secret+"\",\"deviceLabel\":\"Phone\"}";}
 CrewStartService.RedemptionReceipt receipt(){return new CrewStartService.RedemptionReceipt(reg,2,code,"ORIGINAL","START",Instant.EPOCH,run,1,0,device,1,"0");}
 @Test void ordinaryAuthenticatedCaptainRouteReturnsExactReceiptWithoutToken()throws Exception{when(service.redeem(any(),any(),any(),any(),anyLong(),any(),any(),any())).thenReturn(receipt());mvc.perform(post(base+"/code-redemptions").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isOk()).andExpect(jsonPath("$.effect").value("START")).andExpect(jsonPath("$.individualStartedAt").value("1970-01-01T00:00:00Z")).andExpect(jsonPath("$.pointsAdjustment").value("0")).andExpect(jsonPath("$.deviceGeneration").value(1)).andExpect(jsonPath("$.deviceSecret").doesNotExist()).andExpect(jsonPath("$.token").doesNotExist()).andExpect(jsonPath("$.code").doesNotExist()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(header().doesNotExist("Set-Cookie"));verify(attempts).source(any());}
 @Test void anonymousRequestsAreThrottledButCannotRedeem()throws Exception{mvc.perform(post(base+"/code-redemptions").header("X-Rallye-Client","mobile").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isUnauthorized());verify(attempts).source(any());verifyNoInteractions(service);}
 @Test void cookieWritesRequireCsrf()throws Exception{when(service.redeem(any(),any(),any(),any(),anyLong(),any(),any(),any())).thenReturn(receipt());Cookie cookie=new Cookie(AuthCookies.NAME,token);mvc.perform(post(base+"/code-redemptions").cookie(cookie).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isForbidden()).andExpect(header().string("Referrer-Policy","no-referrer"));mvc.perform(post(base+"/code-redemptions").cookie(cookie).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isOk());verify(service,times(1)).redeem(any(),any(),any(),any(),anyLong(),any(),any(),any());}
 @Test void adminIsRequiredForRevocationAndDtoKeepsHistoricalGenerations()throws Exception{String url=base+"/devices/"+device+"/revocations",json="{\"registrationVersion\":2,\"deviceGeneration\":1}";mvc.perform(post(url).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(json)).andExpect(status().isForbidden());when(auth.isAdministrator(actor)).thenReturn(true);when(service.revoke(any(),any(),any(),any(),any(),anyLong(),anyLong(),any())).thenReturn(new CrewStartService.RevocationReceipt(UUID.randomUUID(),reg,3,device,1,2,"REVOKED",Instant.EPOCH,run));mvc.perform(post(url).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(json)).andExpect(status().isOk()).andExpect(jsonPath("$.revokedDeviceGeneration").value(1)).andExpect(jsonPath("$.deviceGeneration").value(2)).andExpect(jsonPath("$.state").value("REVOKED"));verifyNoInteractions(attempts);}
 @Test void malformedRequestsHaveSourceProtectionAndSafe400()throws Exception{for(String json:List.of("null","{}",body().replace(":1,",":-1,"),body().replace(":1,",":1.5,"),body().replace("\"ABC123\"","null"),body().replace("}",",\"kind\":\"ORIGINAL\"}"))){mvc.perform(post(base+"/code-redemptions").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(json)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_REQUEST"));}mvc.perform(post(base+"/code-redemptions").header("Authorization","Bearer "+token).contentType("application/json").content(body())).andExpect(status().isBadRequest());verify(attempts,times(7)).source(any());verifyNoInteractions(service);}
 @Test void sourceLimitRunsBeforeSecurityAndErrorHasPrivacyHeaders()throws Exception{doThrow(new AuthFailure(429,"TOO_MANY_ATTEMPTS")).when(attempts).source(any());mvc.perform(post(base+"/code-redemptions").contentType("application/json").content("malformed")).andExpect(status().isTooManyRequests()).andExpect(jsonPath("$.code").value("TOO_MANY_ATTEMPTS")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Referrer-Policy","no-referrer"));verifyNoInteractions(service);}
 @Test void raceCredentialCannotAuthenticateAccountOrStartApi()throws Exception{for(String path:List.of("/api/v1/auth/me",base+"/start-status"))mvc.perform(get(path).header("Authorization","Race "+secret)).andExpect(status().isUnauthorized());mvc.perform(post(base+"/code-redemptions").header("X-Rallye-Client","mobile").header("Authorization","Race "+secret).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isUnauthorized());verifyNoInteractions(service);}
 @Test void statusRouteIsAvailableToAccountAndReturnsNoCodeOrHash()throws Exception{when(service.status(actor,event,reg)).thenReturn(new CrewStartService.StartStatus(reg,1,Instant.EPOCH,"RUNNING",null,true,null,null,false,"PARTICIPATION_NOT_STARTED",0,null));mvc.perform(get(base+"/start-status").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.canStart").value(true)).andExpect(jsonPath("$.canTakeOver").value(false)).andExpect(jsonPath("$.activeDevice").isEmpty()).andExpect(jsonPath("$.code").doesNotExist()).andExpect(header().string("Referrer-Policy","no-referrer"));}
 @Test void safeBusinessErrorAndRedactedDto()throws Exception{when(service.redeem(any(),any(),any(),any(),anyLong(),any(),any(),any())).thenThrow(new AuthFailure(409,"START_CODE_INVALID"));mvc.perform(post(base+"/code-redemptions").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("START_CODE_INVALID")).andExpect(jsonPath("$.deviceSecret").doesNotExist());assertFalse(new CrewStartController.Redeem(null,null,null,null).toString().contains("deviceSecret"));}
}
